import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"21. Index och Query-prestanda","description":"","frontmatter":{},"headers":[],"relativePath":"sv/chapters/21-index-och-frageprestanda.md","filePath":"sv/chapters/21-index-och-frageprestanda.md"}'),n={name:"sv/chapters/21-index-och-frageprestanda.md"};function r(l,a,d,p,k,h){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="_21-index-och-query-prestanda" tabindex="-1">21. Index och Query-prestanda <a class="header-anchor" href="#_21-index-och-query-prestanda" aria-label="Permalink to &quot;21. Index och Query-prestanda&quot;">​</a></h1><p>När vi skriver en Query beskriver vi vilken information vi vill ha. Vi säger inte nödvändigtvis exakt <strong>hur</strong> databashanteraren ska hitta den.</p><p>Det spelar kanske ingen större roll när bokhandeln har fem produkter och några kunder. Men vad händer om den får hundratusentals produkter, miljontals beställningar och många användare som söker samtidigt?</p><p>Samma Query kan fortfarande ge rätt resultat – men ta mycket olika lång tid att utföra.</p><p>För att förstå varför behöver vi skilja mellan <strong>Queryns betydelse</strong> och <strong>databasens arbete med att utföra den</strong>.</p><h2 id="grund" tabindex="-1">Grund <a class="header-anchor" href="#grund" aria-label="Permalink to &quot;Grund&quot;">​</a></h2><h3 id="hur-hittar-databasen-en-rad" tabindex="-1">Hur hittar databasen en rad? <a class="header-anchor" href="#hur-hittar-databasen-en-rad" aria-label="Permalink to &quot;Hur hittar databasen en rad?&quot;">​</a></h3><p>Vi börjar med vår bekanta tabell <code>products</code>:</p><table tabindex="0"><thead><tr><th>id</th><th>title</th><th style="text-align:right;">price</th><th style="text-align:right;">stock</th><th style="text-align:right;">product_type_id</th></tr></thead><tbody><tr><td>1</td><td>Vägen hem</td><td style="text-align:right;">200.00</td><td style="text-align:right;">12</td><td style="text-align:right;">1</td></tr><tr><td>2</td><td>Den blå staden</td><td style="text-align:right;">150.00</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>3</td><td>Vinterljus</td><td style="text-align:right;">249.00</td><td style="text-align:right;">4</td><td style="text-align:right;">1</td></tr><tr><td>4</td><td>Små historier</td><td style="text-align:right;">120.00</td><td style="text-align:right;">25</td><td style="text-align:right;">2</td></tr><tr><td>5</td><td>Mellan raderna</td><td style="text-align:right;">180.00</td><td style="text-align:right;">9</td><td style="text-align:right;">2</td></tr></tbody></table><p>Vi vill hämta en bestämd produkt:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Databasen skulle kunna läsa varje rad och kontrollera om <code>id</code> är <code>3</code>.</p><p>Det kallas ofta en <strong>tabellskanning</strong> (<em>table scan</em>). Med fem rader är det knappast ett problem. Med fem miljoner rader kan det däremot bli dyrt.</p><p>Ett <strong>index</strong> ger databashanteraren en annan möjlighet att hitta rätt rader.</p><h3 id="vad-ar-ett-index" tabindex="-1">Vad är ett index? <a class="header-anchor" href="#vad-ar-ett-index" aria-label="Permalink to &quot;Vad är ett index?&quot;">​</a></h3><p>Vi kan jämföra ett databasindex med ett sakregister i en bok.</p><p>Om vi söker efter ordet <em>transaktion</em> kan vi slå upp det i registret och få en hänvisning till rätt sidor, i stället för att läsa hela boken från början.</p><p>Ett databasindex fungerar inte exakt som ett bokregister, men grundidén är densamma: <strong>en extra struktur hjälper oss att hitta information utan att undersöka allt</strong>.</p><p>Många vanliga databasindex bygger på trädstrukturer, ofta B-träd eller närbesläktade varianter. Exakt utformning varierar mellan databassystemen.</p><h3 id="primarnyckeln-har-ofta-redan-ett-index" tabindex="-1">Primärnyckeln har ofta redan ett index <a class="header-anchor" href="#primarnyckeln-har-ofta-redan-ett-index" aria-label="Permalink to &quot;Primärnyckeln har ofta redan ett index&quot;">​</a></h3><p>Vi har tidigare bestämt att <code>id</code> är primärnyckel i <code>products</code>.</p><p>I många SQL-system skapas eller används ett index automatiskt för primärnyckeln.</p><p>Det innebär att vår Query med <code>WHERE id = 3</code> ofta redan kan använda ett index.</p><p>Vi ska därför <strong>inte automatiskt skapa ännu ett index på <code>id</code></strong>.</p><p>Hur primärnyckeln lagras och vilka index som finns kan vi undersöka i databassystemets metadata.[^primary-index]</p><p>[^primary-index]: MySQL/InnoDB lagrar normalt tabellens data organiserade kring ett klustrat primärnyckelindex. PostgreSQL skapar ett unikt B-trädsindex för en primärnyckel, men tabellens rader lagras normalt separat. SQL Server kan använda klustrade eller icke-klustrade index.</p><h3 id="skapa-ett-index-med-create-index" tabindex="-1">Skapa ett index med CREATE INDEX <a class="header-anchor" href="#skapa-ett-index-med-create-index" aria-label="Permalink to &quot;Skapa ett index med CREATE INDEX&quot;">​</a></h3><p>Anta att bokhandelns personal ofta söker efter produkter utifrån titeln:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id, title, price</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Vägen hem&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Vi kan skapa ett index på <code>title</code>:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> INDEX</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> idx_products_title</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products (title);</span></span></code></pre></div><p>Nu finns det en indexstruktur som databashanteraren <strong>kan välja</strong> att använda för sökningar på titlar.</p><p>Att skapa ett index innebär inte att varje relevant Query alltid använder det. Databashanteraren väljer en exekveringsplan utifrån bland annat tabellstorlek, statistik och vad den uppskattar blir effektivast.</p><p>Med vår lilla övningstabell kan en fullständig skanning fortfarande vara enklare.</p><h3 id="flera-kolumner-i-ett-index" tabindex="-1">Flera kolumner i ett index <a class="header-anchor" href="#flera-kolumner-i-ett-index" aria-label="Permalink to &quot;Flera kolumner i ett index&quot;">​</a></h3><p>Anta att vi ofta vill hitta tillgängliga produkter av en viss typ, sorterade efter pris:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> title, price</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> product_type_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> price;</span></span></code></pre></div><p>Vi kan överväga ett sammansatt index:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> INDEX</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> idx_products_type_price</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products (product_type_id, price);</span></span></code></pre></div><p>Indexet är ordnat med <code>product_type_id</code> som första indexkolumn och <code>price</code> som andra.</p><p>Det kan vara användbart när vi filtrerar på produkttyp och därefter vill läsa produkterna i prisordning.</p><p>Men vårt villkor <code>stock &gt; 0</code> kan fortfarande kräva ytterligare arbete. Ett index löser inte automatiskt alla delar av en Query.</p><h3 id="ordningen-i-ett-sammansatt-index" tabindex="-1">Ordningen i ett sammansatt index <a class="header-anchor" href="#ordningen-i-ett-sammansatt-index" aria-label="Permalink to &quot;Ordningen i ett sammansatt index&quot;">​</a></h3><p>Ordningen mellan indexkolumnerna spelar roll.</p><p>Ett index på:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(product_type_id, price)</span></span></code></pre></div><p>är inte generellt likvärdigt med ett index på:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(price, product_type_id)</span></span></code></pre></div><p>Det första är ofta mer användbart om vi börjar med att söka på en bestämd produkttyp.</p><p>Vi kan tänka på det som ett register sorterat först efter produkttyp, sedan efter pris inom varje produkttyp.</p><p>Det finns undantag och olika optimeringar i olika system, men ordningen är en viktig del av indexets utformning.</p><h3 id="hur-vet-vi-om-ett-index-anvands" tabindex="-1">Hur vet vi om ett index används? <a class="header-anchor" href="#hur-vet-vi-om-ett-index-anvands" aria-label="Permalink to &quot;Hur vet vi om ett index används?&quot;">​</a></h3><p>För att undersöka hur databashanteraren planerar att köra en Query kan vi använda <code>EXPLAIN</code>:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EXPLAIN</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id, title, price</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Vägen hem&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>I MySQL kan resultatet bland annat ge information om vilka tabeller som läses, vilka index som skulle kunna användas och vilket index som valdes.</p><p>Vi kan också undersöka hur en Query planeras när vi filtrerar och sorterar:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EXPLAIN</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> title, price</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> product_type_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> price;</span></span></code></pre></div><p><strong>En exekveringsplan</strong> beskriver vilka operationer databasen tänker använda. Det är en möjlighet att förstå <em>hur</em> databasen försöker besvara Queryn, inte bara <em>vad</em> Queryn betyder.</p><p>Vi redovisar inget fast resultat från <code>EXPLAIN</code> här, eftersom det beror på databas, version, statistik, index och mängden data.[^explain]</p><p>[^explain]: MySQL, PostgreSQL, SQLite och SQL Server har verktyg för att se exekveringsplaner, men kommandon och presentationsformat varierar. MySQL och PostgreSQL använder exempelvis <code>EXPLAIN</code>, SQLite erbjuder <code>EXPLAIN QUERY PLAN</code> och SQL Server har egna sätt att visa uppskattade och faktiska exekveringsplaner.</p><h2 id="avancerat" tabindex="-1">Avancerat <a class="header-anchor" href="#avancerat" aria-label="Permalink to &quot;Avancerat&quot;">​</a></h2><h3 id="att-uppskatta-kostnaden-for-en-query" tabindex="-1">Att uppskatta kostnaden för en Query <a class="header-anchor" href="#att-uppskatta-kostnaden-for-en-query" aria-label="Permalink to &quot;Att uppskatta kostnaden för en Query&quot;">​</a></h3><p>En databashanterare kan ofta välja mellan flera vägar till samma resultat.</p><p>Den kan läsa hela tabellen, följa ett index, kombinera olika index eller välja mellan flera sätt att genomföra en <code>JOIN</code>.</p><p>Optimeraren försöker uppskatta kostnaden för alternativen utifrån tillgänglig information, exempelvis:</p><ul><li>Hur många rader en tabell innehåller.</li><li>Hur stor andel av raderna som sannolikt uppfyller ett villkor.</li><li>Vilka index som finns och hur de är organiserade.</li><li>Kostnaden för att läsa data, sortera och kombinera rader.</li></ul><p>Det är viktigt att förstå att en plan kan bygga på <strong>uppskattningar</strong>, inte fullständig förhandskunskap om resultatet.</p><h3 id="selektivitet-–-hur-mycket-valjer-vi-ut" tabindex="-1">Selektivitet – hur mycket väljer vi ut? <a class="header-anchor" href="#selektivitet-–-hur-mycket-valjer-vi-ut" aria-label="Permalink to &quot;Selektivitet – hur mycket väljer vi ut?&quot;">​</a></h3><p>Anta att nästan alla produkter har <code>stock &gt; 0</code>.</p><p>Ett index på <code>stock</code> kanske inte hjälper särskilt mycket för:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Om Queryn ändå ska hämta nästan hela tabellen kan det vara effektivare att läsa den direkt.</p><p>Men ett index på en kolumn som ofta används för att hitta <strong>en mycket liten andel</strong> av raderna kan vara värdefullt.</p><p>Det brukar beskrivas med begreppet <strong>selektivitet</strong>.</p><p>Samtidigt räcker det inte att en kolumn har många olika värden för att ett index alltid ska vara bra. Vi måste se till de faktiska sökningarna.</p><h3 id="index-hjalper-aven-vid-join" tabindex="-1">Index hjälper även vid JOIN <a class="header-anchor" href="#index-hjalper-aven-vid-join" aria-label="Permalink to &quot;Index hjälper även vid JOIN&quot;">​</a></h3><p>Vi har kopplat produkter till produkttyper med <code>product_type_id</code>.</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> product_type</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> p</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INNER JOIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> product_types </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> t</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">product_type_id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Index på kolumner som används i relationsvillkor kan hjälpa databashanteraren att hitta matchande rader.</p><p>Men det betyder inte att varje <code>JOIN</code> alltid bör använda index. Om stora delar av tabellerna ändå behöver kombineras kan databasen välja andra strategier.</p><p>Index på främmande nycklar är därför ofta användbara, men vi ska inte utgå från att de skapas automatiskt i alla SQL-system.[^fk-index]</p><p>[^fk-index]: MySQL/InnoDB kräver index som stöd för främmande nyckelrelationer och kan skapa saknade stödindex automatiskt. PostgreSQL skapar däremot inte automatiskt index på den refererande kolumnen enbart för att en främmande nyckel definieras.</p><h3 id="covering-index-–-nar-indexet-racker" tabindex="-1">Covering index – när indexet räcker <a class="header-anchor" href="#covering-index-–-nar-indexet-racker" aria-label="Permalink to &quot;Covering index – när indexet räcker&quot;">​</a></h3><p>Titta på denna Query:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> product_type_id, price</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> product_type_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> price;</span></span></code></pre></div><p>Om vi har ett sammansatt index på <code>(product_type_id, price)</code> kan indexet i vissa system innehålla allt som behövs för att besvara Queryn.</p><p>Då behöver databashanteraren kanske inte läsa själva tabellraderna separat. Detta brukar kallas ett <strong>covering index</strong>, eller en index-only-liknande läsning.</p><p>Men en sådan optimering beror på indexets lagring, databassystemet och ibland synlighetsinformation om raderna.</p><h3 id="varfor-fungerar-inte-alltid-en-indexerad-sokning" tabindex="-1">Varför fungerar inte alltid en indexerad sökning? <a class="header-anchor" href="#varfor-fungerar-inte-alltid-en-indexerad-sokning" aria-label="Permalink to &quot;Varför fungerar inte alltid en indexerad sökning?&quot;">​</a></h3><p>Ett index på <code>title</code> kan vara användbart när vi jämför en titel med ett exakt värde:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Vägen hem&#39;</span></span></code></pre></div><p>Det kan ibland också hjälpa för ett prefix:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Vägen%&#39;</span></span></code></pre></div><p>Men en sökning med ett inledande jokertecken:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIKE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%vägen%&#39;</span></span></code></pre></div><p>kan ofta inte utnyttja ett vanligt B-trädsindex på samma sätt.</p><p>Vilket index som kan användas påverkas också av kollationer och databasens hantering av text.</p><p>Det här är ett exempel på att <strong>hur vi uttrycker ett villkor</strong> kan påverka vilka sökvägar databasen har tillgång till.</p><h3 id="nar-vi-anvander-funktioner-i-villkor" tabindex="-1">När vi använder funktioner i villkor <a class="header-anchor" href="#nar-vi-anvander-funktioner-i-villkor" aria-label="Permalink to &quot;När vi använder funktioner i villkor&quot;">​</a></h3><p>Anta att vi vill jämföra ett omvandlat värde:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> LOWER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(title) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;vägen hem&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Ett vanligt index på <code>title</code> är inte nödvändigtvis direkt användbart för villkoret <code>LOWER(title)</code>.</p><p>Vissa databassystem erbjuder uttrycksindex eller andra lösningar för sådana fall. Men vi behöver undersöka vilket stöd den faktiska databasen har.</p><p>Det är alltså inte så att SQL-funktioner är problematiska i sig, utan att de kan förändra <strong>vilket uttryck databasen behöver söka efter</strong>.</p><h3 id="index-har-en-kostnad" tabindex="-1">Index har en kostnad <a class="header-anchor" href="#index-har-en-kostnad" aria-label="Permalink to &quot;Index har en kostnad&quot;">​</a></h3><p>Varje index tar lagringsutrymme.</p><p>När vi lägger till en produkt eller ändrar ett indexerat värde kan databasen också behöva uppdatera indexstrukturen.</p><p>Därför påverkar index inte bara läsningar utan även <code>INSERT</code>, <code>UPDATE</code> och <code>DELETE</code>.</p><p>Det skapar en avvägning:</p><table tabindex="0"><thead><tr><th>Fler index kan ge</th><th>Men innebär också</th></tr></thead><tbody><tr><td>Snabbare sökningar för vissa Queries</td><td>Mer lagringsutrymme</td></tr><tr><td>Effektivare vissa <code>JOIN</code> och sorteringar</td><td>Mer arbete vid förändringar av data</td></tr><tr><td>Bättre stöd för vissa åtkomstmönster</td><td>Fler strukturer att underhålla och förstå</td></tr></tbody></table><p>Vi bör alltså inte skapa index på varje kolumn bara för säkerhets skull.</p><h3 id="att-undersoka-en-verklig-prestandafraga" tabindex="-1">Att undersöka en verklig prestandafråga <a class="header-anchor" href="#att-undersoka-en-verklig-prestandafraga" aria-label="Permalink to &quot;Att undersöka en verklig prestandafråga&quot;">​</a></h3><p>Anta att personalen upplever att en produktsökning blivit långsam.</p><p>Vi kan arbeta systematiskt:</p><ol><li><strong>Beskriv problemet.</strong> Vilken Query är långsam, hur ofta körs den och hur mycket data läser den?</li><li><strong>Studera planen.</strong> Använd <code>EXPLAIN</code> och undersök tabellskanningar, sorteringar, index och uppskattade radantal.</li><li><strong>Formulera en hypotes.</strong> Skulle exempelvis ett index på en viss kombination av kolumner hjälpa?</li><li><strong>Prova och mät.</strong> Jämför samma Query och liknande data före och efter ändringen.</li><li><strong>Värdera helheten.</strong> Förbättrades läsningen utan att skrivningar, lagringskostnad eller andra Queries påverkades orimligt mycket?</li></ol><p>I flera databassystem går det också att mäta faktisk exekvering och jämföra uppskattade med verkliga radantal. Sådana mätningar behöver göras med omsorg: att köra en Query kan belasta systemet, och mätresultat påverkas av cache och parallella aktiviteter.[^analyze]</p><p>[^analyze]: PostgreSQL erbjuder <code>EXPLAIN ANALYZE</code> och nyare MySQL-versioner har <code>EXPLAIN ANALYZE</code>. De kör normalt Queryn och mäter exekveringen. För dataförändrande satser behöver detta särskild försiktighet eftersom själva förändringen kan utföras.</p><h3 id="prestanda-handlar-ocksa-om-modellering" tabindex="-1">Prestanda handlar också om modellering <a class="header-anchor" href="#prestanda-handlar-ocksa-om-modellering" aria-label="Permalink to &quot;Prestanda handlar också om modellering&quot;">​</a></h3><p>Vi har tidigare lärt oss att tabeller ska beskriva tydliga företeelser och relationer.</p><p>Nu kan vi se att datamodellen påverkar vilka Queries som behöver skrivas och vilka index som är användbara.</p><p>En modell med tydliga nycklar och relationer gör det ofta lättare att förstå hur information ska kombineras. Men en väl normaliserad modell är inte automatiskt optimal för varje analytiskt informationsbehov.</p><p>I vissa system kan vi behöva komplettera den operativa modellen med Views, särskilda sammanställningar eller andra representationsformer.</p><p>Det betyder inte att vi ska överge våra principer om dataintegritet. Det betyder att vi måste förstå <strong>vilken användning en viss modell är byggd för</strong>.</p><h3 id="ratt-svar-och-ratt-arbetsinsats" tabindex="-1">Rätt svar och rätt arbetsinsats <a class="header-anchor" href="#ratt-svar-och-ratt-arbetsinsats" aria-label="Permalink to &quot;Rätt svar och rätt arbetsinsats&quot;">​</a></h3><p>Två Queries kan ge exakt samma resultat men kräva olika mycket arbete av databashanteraren.</p><p>Och samma Query kan köras med olika exekveringsplaner när mängden data förändras.</p><p>Vi behöver därför kunna resonera på två nivåer:</p><p><strong>Vad betyder vår Query?</strong> Vilken information beskriver resultatet?</p><p><strong>Hur kan databasen ta fram det?</strong> Vilka strukturer, operationer och resurser behövs?</p><p>Att förstå båda nivåerna hjälper oss att skapa system som inte bara ger korrekta svar, utan också fungerar när verksamheten växer.</p><h2 id="reflektion" tabindex="-1">Reflektion <a class="header-anchor" href="#reflektion" aria-label="Permalink to &quot;Reflektion&quot;">​</a></h2><ol><li>Varför kan ett index vara mycket användbart för en Query men nästan värdelöst för en annan?</li><li>Varför skapar vi inte bara så många index som möjligt?</li><li>Vad är skillnaden mellan att förbättra en Querys logiska tydlighet och att förbättra dess faktiska exekveringsprestanda?</li></ol>`,132)])])}const c=e(n,[["render",r]]);export{g as __pageData,c as default};
